  const SHOW_IP_ROUTE = 'Codes: L - local, C - connected, S - static, R - RIP, M - mobile, B - BGP\n       D - EIGRP, EX - EIGRP external, O - OSPF, IA - OSPF inter area\n       N1 - OSPF NSSA external type 1, N2 - OSPF NSSA external type 2\n       E1 - OSPF external type 1, E2 - OSPF external type 2\n       * - candidate default, U - per-user static route\n\nGateway of last resort is 10.0.13.3 to network 0.0.0.0\n\nS*    0.0.0.0/0 [1/0] via 10.0.13.3\n      10.0.0.0/8 is variably subnetted, 6 subnets, 4 masks\nC        10.0.12.0/30 is directly connected, GigabitEthernet0/1\nL        10.0.12.1/32 is directly connected, GigabitEthernet0/1\nC        10.0.13.0/30 is directly connected, GigabitEthernet0/2\nL        10.0.13.1/32 is directly connected, GigabitEthernet0/2\nS        10.2.0.0/16 [1/0] via 10.0.13.3\nO        10.2.2.0/24 [110/2] via 10.0.12.2, 00:12:44, GigabitEthernet0/1\n      192.168.1.0/24 is variably subnetted, 2 subnets, 2 masks\nC        192.168.1.0/24 is directly connected, GigabitEthernet0/0\nL        192.168.1.1/32 is directly connected, GigabitEthernet0/0';

  const M3 = {
    id: 'ccna-3', order: 3, title: '3.0 IP Connectivity (25%)', exam: '3.0 IP Connectivity (25%)',
    desc: 'Πώς σκέφτεται ένας router: routing table, longest prefix match, administrative distance, static routes (IPv4/IPv6), OSPFv2 και FHRP.',
    lessons: [
      {
        id: 'ccna-3-1', title: 'Ο routing table: τι σημαίνει κάθε κομμάτι', minutes: 18,
        goal: 'Να διαβάζεις το `show ip route` και να αναγνωρίζεις routing protocol code, prefix, mask, next hop, administrative distance, metric και gateway of last resort.',
        blocks: [
          { t: 'text', md: 'Ο **routing table** είναι ο **χάρτης** του router: για κάθε προορισμό (δίκτυο) λέει «στείλ’ το από εκείνη την πόρτα, σε εκείνον τον γείτονα». Ο router **δεν** ξέρει όλη τη διαδρομή μέχρι το τέλος, ξέρει μόνο το **επόμενο βήμα (next hop)**. Σαν τις πινακίδες στην εθνική οδό: «Θεσσαλονίκη → δεξιά».\n\n### Από πού μαθαίνει routes\n- **Connected (C)** και **Local (L)**: αυτόματα, μόλις ένα interface έχει IP και είναι **up/up**. Το L είναι η /32 της ίδιας της IP του interface.\n- **Static (S)**: τις γράφεις εσύ με το χέρι.\n- **Dynamic**: από routing protocols, π.χ. **O** = OSPF, **D** = EIGRP, **R** = RIP, **B** = BGP.' },
          { t: 'code', lang: 'text', title: 'R1# show ip route', code: SHOW_IP_ROUTE,
            explain: '- **Code** (πρώτη στήλη): από πού ήρθε η route. Το `*` σημαίνει **candidate default**.\n- **Prefix/mask**: π.χ. `10.2.2.0/24`, ο προορισμός.\n- **[110/2]**: **[administrative distance / metric]**. 110 = OSPF, 2 = κόστος OSPF.\n- **via 10.0.12.2**: η **next-hop** IP.\n- **00:12:44**: πόσο καιρό υπάρχει η route (μόνο για dynamic).\n- **GigabitEthernet0/1**: το **exit interface**.\n- **Gateway of last resort**: το **default route** (0.0.0.0/0), για ό,τι δεν ταιριάζει πουθενά αλλού.\n- Οι γραμμές «is variably subnetted, 6 subnets, 4 masks» είναι απλώς επικεφαλίδες που ομαδοποιούν ανά classful δίκτυο.' },
          { t: 'anim', scene: 'ccna-routing-lookup', caption: 'Αναζήτηση στον routing table με longest prefix match.' },
          { t: 'cli', title: 'Lab: εξερεύνησε τον routing table', prompt: 'R1#',
            steps: [
              { task: 'Δες όλο τον routing table.', expect: '^' + SH + 'ip\\s+ro(ute)?$', ans: 'show ip route', out: SHOW_IP_ROUTE },
              { task: 'Ρώτα τον router **ποια route θα χρησιμοποιούσε** για το 10.2.2.50: `show ip route 10.2.2.50`.', expect: '^' + SH + 'ip\\s+ro(ute)?\\s+' + ip('10.2.2.50') + '$', ans: 'show ip route 10.2.2.50',
                out: 'Routing entry for 10.2.2.0/24\n  Known via "ospf 1", distance 110, metric 2, type intra area\n  Last update from 10.0.12.2 on GigabitEthernet0/1, 00:12:51 ago\n  Routing Descriptor Blocks:\n  * 10.0.12.2, from 2.2.2.2, 00:12:51 ago, via GigabitEthernet0/1\n      Route metric is 2, traffic share count is 1' },
              { task: 'Δες μόνο τις **static** routes: `show ip route static`.', expect: '^' + SH + 'ip\\s+ro(ute)?\\s+stat(ic)?$', ans: 'show ip route static',
                out: 'S*    0.0.0.0/0 [1/0] via 10.0.13.3\n      10.0.0.0/8 is variably subnetted, 6 subnets, 4 masks\nS        10.2.0.0/16 [1/0] via 10.0.13.3' },
            ], done: 'Το `show ip route <IP>` είναι το πιο γρήγορο εργαλείο troubleshooting: σου λέει **ακριβώς** ποια εγγραφή θα κερδίσει.' },
          { t: 'exam', md: 'Ερωτήσεις τύπου «ποια είναι η AD / metric / next hop της route προς Χ» θέλουν να διαβάσεις τις αγκύλες: **[AD/metric]**. Τα **Connected** έχουν AD **0** και τα **Static** AD **1** (δείχνουν `[1/0]`). Οι γραμμές **L** (/32) είναι οι IP του ίδιου του router.' },
          { t: 'quiz', q: 'Στη γραμμή `O 10.2.2.0/24 [110/2] via 10.0.12.2`, τι σημαίνει το **2**;', opts: ['Administrative distance', 'Το metric (κόστος OSPF)', 'Πόσα hops μέχρι τον προορισμό', 'Τον αριθμό του interface'], ok: 1, why: 'Η μορφή είναι **[AD/metric]**: 110 = AD του OSPF, 2 = **metric** (cost).' },
          { t: 'quiz', q: 'Τι είναι το **Gateway of last resort**;', opts: ['Ο DHCP server', 'Το default route που χρησιμοποιείται όταν δεν ταιριάζει καμία άλλη route', 'Το HSRP virtual IP', 'Το πρώτο connected δίκτυο'], ok: 1, why: 'Είναι το next hop του **0.0.0.0/0**: ο «αν δεν ξέρεις, στείλ’ το εκεί».' },
        ],
      },
      {
        id: 'ccna-3-2', title: 'Η απόφαση προώθησης: longest prefix match, AD, metric', minutes: 18,
        goal: 'Να εφαρμόζεις με τη σωστή σειρά longest prefix match, administrative distance και metric για να βρεις ποια route κερδίζει.',
        blocks: [
          { t: 'text', md: 'Ο router παίρνει **δύο διαφορετικές** αποφάσεις, και η εξέταση λατρεύει να τις μπερδεύει:\n\n### Α. Ποια route **μπαίνει** στον routing table; (για το **ίδιο** prefix)\nΑν δύο πηγές προτείνουν **το ίδιο ακριβώς prefix** (π.χ. 10.1.1.0/24 από OSPF και από static):\n1. Κερδίζει η χαμηλότερη **Administrative Distance (AD)**, δηλαδή πόσο **εμπιστευόμαστε** την πηγή.\n2. Αν η πηγή είναι η ίδια (π.χ. δύο OSPF routes), κερδίζει το χαμηλότερο **metric**.\n3. Ίδιο metric → **ECMP** (equal-cost multi-path): μπαίνουν **και οι δύο** και γίνεται load balancing.\n\n### Β. Ποια route **χρησιμοποιείται** για ένα πακέτο;\nΑπό όσες routes **ταιριάζουν** στη destination IP, κερδίζει **πάντα** η πιο συγκεκριμένη, δηλαδή το **μεγαλύτερο prefix length**: **longest prefix match**. Η AD δεν συγκρίνεται εδώ, γιατί αφορά μόνο ίδια prefixes.' },
          { t: 'table', head: ['Πηγή route', 'AD'], rows: [
            ['Connected', '**0**'], ['Static', '**1**'], ['eBGP', '20'], ['EIGRP (internal)', '90'], ['**OSPF**', '**110**'], ['IS-IS', '115'], ['RIP', '120'], ['EIGRP external', '170'], ['iBGP', '200'], ['Default route από DHCP (Cisco)', '254'], ['Άγνωστη / μη αξιόπιστη', '**255** (δεν μπαίνει ποτέ)'],
          ] },
          { t: 'text', md: '### Παράδειγμα\nΟ routing table έχει:\n- `D 172.16.0.0/16 [90/…]`\n- `O 172.16.5.0/24 [110/…]`\n- `S 172.16.5.64/26 [1/0]`\n- `S* 0.0.0.0/0`\n\nΠακέτο για **172.16.5.70**: ταιριάζουν όλα! Το .70 είναι μέσα στο 172.16.5.64/26 (.64–.127). Κερδίζει το **/26** (static).\nΠακέτο για **172.16.5.10**: ταιριάζουν /16, /24, /0. Κερδίζει το **/24** (OSPF), **παρότι** το EIGRP έχει καλύτερη AD, γιατί πρόκειται για διαφορετικά prefixes.\nΠακέτο για **172.16.9.9**: κερδίζει το **/16** (EIGRP).\nΠακέτο για **8.8.8.8**: μόνο το **default**.' },
          { t: 'tip', md: 'Μνημονικό σειράς: **«Πρώτα το μήκος (prefix), μετά η εμπιστοσύνη (AD), μετά η απόσταση (metric)»**. Για την εξέταση: το LPM αποφασίζει **ανά πακέτο**, ενώ AD και metric αποφασίζουν **ποιες routes υπάρχουν** στον πίνακα.' },
          { t: 'exam', md: 'Αν η ερώτηση δίνει routes **με διαφορετικά prefix lengths** και ρωτά «από πού θα φύγει το πακέτο», **αγνόησε την AD** και ψάξε το μεγαλύτερο prefix που **περιέχει** τη διεύθυνση. Αν δίνει το **ίδιο** prefix από διαφορετικά protocols, ρωτά για **AD**. Μάθε τον πίνακα AD απ’ έξω: 0, 1, 20, 90, 110, 115, 120, 170, 200, 255.' },
          { t: 'quiz', q: 'Ο router μαθαίνει το **10.5.0.0/16** από OSPF και το **ίδιο** 10.5.0.0/16 από EIGRP. Ποιο μπαίνει στον routing table;', opts: ['OSPF (110)', 'EIGRP (90)', 'Και τα δύο', 'Αυτό με το μικρότερο metric'], ok: 1, why: 'Ίδιο prefix → συγκρίνεται η **AD**: EIGRP 90 < OSPF 110. Τα metrics διαφορετικών protocols δεν συγκρίνονται.' },
          { t: 'quiz', q: 'Routes: `S 192.168.0.0/16`, `O 192.168.1.0/24`, `O 192.168.1.128/25`. Πού πάει πακέτο για **192.168.1.100**;', opts: ['192.168.0.0/16', '192.168.1.0/24', '192.168.1.128/25', 'Πετιέται'], ok: 1, why: 'Το .100 **δεν** ανήκει στο .128/25 (.128–.255). Από τα υπόλοιπα, το **/24** είναι το πιο συγκεκριμένο.' },
          { t: 'quiz', q: 'Ποια είναι η AD μιας **static** route (χωρίς ρύθμιση);', opts: ['0', '1', '5', '110'], ok: 1, why: 'Static = **1**. Connected = 0.' },
        ],
      },
      {
        id: 'ccna-3-3', title: 'Static routes IPv4 & IPv6: network, host, default, floating', minutes: 24,
        goal: 'Να ρυθμίζεις IPv4 και IPv6 static routes (network, host, default, floating), να ξέρεις τη διαφορά next-hop, exit interface και fully specified, και να ελέγχεις με `show ip route`.',
        blocks: [
          { t: 'text', md: 'Η **static route** είναι ένας κανόνας που γράφεις εσύ: «για το δίκτυο Χ, πήγαινε στο Υ». Δεν προσαρμόζεται αν κάτι αλλάξει (εκτός αν πέσει το interface), αλλά είναι απλή, ασφαλής και δεν καταναλώνει πόρους. Ιδανική για μικρά δίκτυα, για τη **σύνδεση με τον ISP (default route)** και για **backup**.\n\n### Σύνταξη IPv4\n`ip route <δίκτυο> <μάσκα> {next-hop IP | exit interface | interface + next-hop} [AD]`' },
          { t: 'table', head: ['Είδος', 'Παράδειγμα', 'Σχόλιο'], rows: [
            ['Network route', '`ip route 192.168.2.0 255.255.255.0 10.0.12.2`', 'Recursive: ο router ψάχνει πώς φτάνει στο 10.0.12.2'],
            ['Host route', '`ip route 10.9.9.9 255.255.255.255 10.0.12.2`', 'Μάσκα /32: ένας μόνο host'],
            ['Default route', '`ip route 0.0.0.0 0.0.0.0 203.0.113.1`', 'Ταιριάζει σε όλα (/0) → gateway of last resort'],
            ['Floating static', '`ip route 0.0.0.0 0.0.0.0 198.51.100.1 10`', 'AD 10 > 1: μπαίνει **μόνο** αν χαθεί η κύρια'],
            ['Directly attached', '`ip route 192.168.2.0 255.255.255.0 g0/1`', 'Σε Ethernet βασίζεται σε proxy ARP: καλύτερα να το αποφεύγεις'],
            ['Fully specified', '`ip route 192.168.2.0 255.255.255.0 g0/1 10.0.12.2`', 'Interface + next hop: ο πιο ρητός τρόπος'],
          ] },
          { t: 'text', md: '### Floating static route\nΜια static route με **AD μεγαλύτερη** από την κύρια route, ώστε να «επιπλέει» αθέατη και να μπαίνει στον πίνακα **μόνο** όταν η κύρια χαθεί.\n- Κύρια = static (AD 1) → backup π.χ. AD **5** ή **10**.\n- Κύρια = μαθημένη από OSPF (AD 110) → η floating πρέπει να έχει AD **> 110**, π.χ. **115** ή **130**. Αλλιώς θα κερδίσει την OSPF route αμέσως!\n\nΠροσοχή: μια static route βγαίνει από τον πίνακα μόνο αν το router καταλάβει ότι το next hop είναι απρόσιτο (π.χ. πέσει το **δικό του** interface). Αν πέσει κάτι πιο πέρα, ο router δεν το ξέρει. Γι’ αυτό σε παραγωγή υπάρχουν μηχανισμοί όπως το IP SLA tracking.\n\n### Static routes στο IPv6\nΊδια λογική, εντολή `ipv6 route` και prefix με `/`. Απαιτεί `ipv6 unicast-routing`. Αν το next hop είναι **link-local** (fe80::), **πρέπει** να δώσεις και το **exit interface**, γιατί η ίδια link-local μπορεί να υπάρχει σε κάθε link.' },
          { t: 'code', lang: 'cisco', title: 'Static routes IPv4 και IPv6', code: '! IPv4\nip route 192.168.2.0 255.255.255.0 10.0.12.2\nip route 10.9.9.9 255.255.255.255 10.0.12.2\nip route 0.0.0.0 0.0.0.0 203.0.113.1\nip route 0.0.0.0 0.0.0.0 198.51.100.1 10\n!\n! IPv6\nipv6 unicast-routing\nipv6 route 2001:db8:2::/64 2001:db8:12::2\nipv6 route 2001:db8:9::9/128 2001:db8:12::2\nipv6 route ::/0 GigabitEthernet0/2 fe80::3\nipv6 route ::/0 2001:db8:99::1 200',
            explain: '- Γραμμή 1: network route προς το LAN του R2.\n- Γραμμή 2: host route (/32).\n- Γραμμή 3: κύρια default route προς ISP-1.\n- Γραμμή 4: **floating** default προς ISP-2 με AD 10. Δεν φαίνεται στον πίνακα όσο υπάρχει η κύρια.\n- `ipv6 route 2001:db8:2::/64 …`: IPv6 network route.\n- `…/128`: IPv6 host route.\n- `ipv6 route ::/0 Gi0/2 fe80::3`: IPv6 default route με **link-local next hop**, άρα **υποχρεωτικά** με interface.\n- Τελευταία γραμμή: IPv6 floating default με AD 200.' },
          { t: 'cli', title: 'Lab: static routes και floating default', prompt: 'R1(config)#', banner: 'R1: Gi0/1 → R2 (10.0.12.2), LAN του R2 = 192.168.2.0/24. ISP-1: 203.0.113.1, ISP-2 (backup): 198.51.100.1',
            steps: [
              { task: 'Πρόσθεσε route για το **192.168.2.0/24** μέσω **10.0.12.2**.', expect: '^ip\\s+route\\s+' + ip('192.168.2.0') + '\\s+' + ip('255.255.255.0') + '\\s+' + ip('10.0.12.2') + '$', ans: 'ip route 192.168.2.0 255.255.255.0 10.0.12.2' },
              { task: 'Πρόσθεσε **default route** προς τον ISP-1 (**203.0.113.1**).', expect: '^ip\\s+route\\s+0\\.0\\.0\\.0\\s+0\\.0\\.0\\.0\\s+' + ip('203.0.113.1') + '$', ans: 'ip route 0.0.0.0 0.0.0.0 203.0.113.1' },
              { task: 'Πρόσθεσε **floating** default route προς τον ISP-2 (**198.51.100.1**) με AD **10**.', expect: '^ip\\s+route\\s+0\\.0\\.0\\.0\\s+0\\.0\\.0\\.0\\s+' + ip('198.51.100.1') + '\\s+10$', ans: 'ip route 0.0.0.0 0.0.0.0 198.51.100.1 10' },
              { task: 'Πρόσθεσε IPv6 route για το **2001:db8:2::/64** μέσω **2001:db8:12::2**.', expect: '^ipv6\\s+route\\s+2001:db8:2::/64\\s+2001:db8:12::2$', ans: 'ipv6 route 2001:db8:2::/64 2001:db8:12::2' },
              { task: 'Γύρνα στο `#`.', expect: RX.end, ans: 'end', next: 'R1#' },
              { task: 'Δες τις static routes.', expect: '^' + SH + 'ip\\s+ro(ute)?\\s+stat(ic)?$', ans: 'show ip route static',
                out: 'Gateway of last resort is 203.0.113.1 to network 0.0.0.0\n\nS*    0.0.0.0/0 [1/0] via 203.0.113.1\nS     192.168.2.0/24 [1/0] via 10.0.12.2' },
              { task: 'Έλεγξε συνδεσιμότητα: `ping 192.168.2.1`.', expect: '^ping\\s+' + ip('192.168.2.1') + '$', ans: 'ping 192.168.2.1',
                out: 'Type escape sequence to abort.\nSending 5, 100-byte ICMP Echos to 192.168.2.1, timeout is 2 seconds:\n!!!!!\nSuccess rate is 100 percent (5/5), round-trip min/avg/max = 1/2/4 ms' },
            ], done: 'Η floating route (AD 10) **δεν** εμφανίζεται, γιατί η κύρια (AD 1) υπάρχει. Αν πέσει το interface προς τον ISP-1, θα εμφανιστεί αυτόματα. Θυμήσου επίσης ότι **ο R2 χρειάζεται route επιστροφής** προς το LAN του R1!' },
          { t: 'warn', md: 'Η πιο συχνή αιτία που «δεν δουλεύει το ping» με static routes: λείπει η **route επιστροφής**. Το πακέτο φτάνει στον προορισμό, αλλά η απάντηση δεν ξέρει πώς να γυρίσει. Το routing πρέπει να υπάρχει **και προς τις δύο κατευθύνσεις**.' },
          { t: 'exam', md: 'Θυμήσου: (1) floating = **μεγαλύτερη** AD από την κύρια. Για backup σε OSPF route χρειάζεται AD > 110. (2) IPv6 με **link-local next hop** απαιτεί **exit interface**. (3) default IPv4 = `0.0.0.0 0.0.0.0`, IPv6 = `::/0`. (4) host route = /32 (IPv4) ή /128 (IPv6). (5) Στο `ping` του IOS, `!` = επιτυχία, `.` = timeout, `U` = unreachable.' },
          { t: 'quiz', q: 'Ο R1 μαθαίνει το 10.10.10.0/24 από OSPF. Θέλεις static backup που θα μπαίνει **μόνο** αν χαθεί η OSPF route. Ποια AD;', opts: ['1', '90', '100', '120'], ok: 3, why: 'Χρειάζεται AD **μεγαλύτερη** από 110 (OSPF). Από τις επιλογές μόνο το **120** είναι.' },
          { t: 'quiz', q: 'Ποια εντολή είναι **έγκυρη** IPv6 default route με link-local next hop;', opts: ['`ipv6 route ::/0 fe80::1`', '`ipv6 route ::/0 g0/0 fe80::1`', '`ip route ::/0 fe80::1`', '`ipv6 route 0.0.0.0/0 fe80::1`'], ok: 1, why: 'Με **link-local** next hop πρέπει να δοθεί και το **interface**.' },
          { t: 'quiz', q: 'Ποια μάσκα χρησιμοποιείς για IPv4 **host route**;', opts: ['0.0.0.0', '255.255.255.0', '255.255.255.252', '255.255.255.255'], ok: 3, why: 'Host route = **/32** = 255.255.255.255.' },
        ],
      },
      {
        id: 'ccna-3-4', title: 'OSPF Ι: link-state, router ID, neighbors και LSDB', minutes: 22,
        goal: 'Να εξηγείς πώς δουλεύει ένα link-state πρωτόκολλο, τι είναι area/LSA/LSDB/SPF, πώς επιλέγεται το router ID, τα 5 είδη OSPF πακέτων, τις καταστάσεις γειτνίασης και τις προϋποθέσεις για να γίνουν δύο routers neighbors.',
        blocks: [
          { t: 'text', md: 'Με static routes σε 50 routers θα έγραφες εκατοντάδες γραμμές, και αν έπεφτε ένα link θα έπρεπε να τις αλλάξεις με το χέρι. Ένα **dynamic routing protocol** κάνει τους routers να **ανταλλάσσουν πληροφορίες** και να βρίσκουν μόνοι τους τις καλύτερες διαδρομές.\n\nΤο **OSPF (Open Shortest Path First)** είναι **link-state** και ανοιχτό πρότυπο. Η αναλογία: κάθε router μοιράζει σε όλους μια **περιγραφή του εαυτού του** («είμαι ο R1, έχω αυτά τα links με αυτά τα κόστη»). Όλοι μαζεύουν όλες τις περιγραφές και φτιάχνουν τον **ίδιο πλήρη χάρτη**. Μετά ο καθένας τρέχει τον αλγόριθμο **SPF (Dijkstra)** για να βρει τις συντομότερες διαδρομές **από τη δική του θέση**.\n\n### Λεξιλόγιο\n- **LSA (Link-State Advertisement)**: η «περιγραφή». **Type 1 (Router LSA)**: κάθε router για τον εαυτό του. **Type 2 (Network LSA)**: από τον DR για ένα multi-access segment.\n- **LSDB (Link-State Database)**: η συλλογή όλων των LSAs, δηλαδή ο χάρτης. **Ίδια** σε όλους τους routers μιας area.\n- **Area**: ομάδα routers που μοιράζονται την ίδια LSDB. Η **area 0** είναι η **backbone**. Στο CCNA ασχολούμαστε με **single-area** OSPF.\n- **Cost**: το metric του OSPF, βασισμένο στο bandwidth.' },
          { t: 'text', md: '### Router ID (RID)\nΈνας 32-bit αριθμός σε μορφή IPv4 που **ταυτοποιεί** τον router στο OSPF. Επιλέγεται με αυτή τη σειρά:\n1. Χειροκίνητα με `router-id 1.1.1.1`\n2. Η **υψηλότερη IP** από **loopback** interfaces που είναι up\n3. Η **υψηλότερη IP** από **ενεργά φυσικά** interfaces\n\nΤο RID επιλέγεται όταν ξεκινά η διεργασία OSPF. Αν το αλλάξεις μετά, χρειάζεται `clear ip ospf process` (ή reload) για να εφαρμοστεί.\n\n### Τα 5 είδη OSPF πακέτων (IP protocol **89**)' },
          { t: 'table', head: ['Type', 'Πακέτο', 'Ρόλος'], rows: [
            ['1', '**Hello**', 'Ανακάλυψη γειτόνων, keepalive, εκλογή DR/BDR'],
            ['2', '**DBD** (Database Description)', 'Περίληψη της LSDB (ποια LSAs έχω)'],
            ['3', '**LSR** (Link-State Request)', '«Στείλε μου αυτά τα LSAs που δεν έχω»'],
            ['4', '**LSU** (Link-State Update)', 'Περιέχει τα πλήρη LSAs'],
            ['5', '**LSAck**', 'Επιβεβαίωση λήψης LSU'],
          ] },
          { t: 'anim', scene: 'ccna-ospf-neighbors', caption: 'Down → Init → 2-Way → ExStart → Exchange → Loading → Full.' },
          { t: 'text', md: '### Για να γίνουν δύο routers neighbors πρέπει να ταιριάζουν:\n- **Area ID** (και ο τύπος της area, π.χ. stub flag)\n- **Subnet και μάσκα** του κοινού link\n- **Hello και Dead timers** (προεπιλογή 10/40 s σε Ethernet)\n- **Authentication** (αν υπάρχει)\n- **MTU**: αν διαφέρει, κολλάνε σε **ExStart/Exchange**\n- Τα **RID** πρέπει να είναι **διαφορετικά**\n- Το interface **δεν** πρέπει να είναι **passive**\n- Συμβατός **network type** (π.χ. broadcast και στις δύο πλευρές)\n\nΤα Hellos στέλνονται στο **224.0.0.5** (AllSPFRouters). Τα μηνύματα προς DR/BDR πηγαίνουν στο **224.0.0.6** (AllDRouters).' },
          { t: 'exam', md: 'Πολύ συχνό: «δύο routers δεν γίνονται neighbors, ποια είναι η αιτία;». Ψάξε **διαφορετική area**, **διαφορετικό subnet**, **διαφορετικούς hello/dead timers**, **passive-interface**, **ίδιο RID**. Το **process ID** (`router ospf 1` και `router ospf 2`) **δεν** χρειάζεται να ταιριάζει, γιατί έχει μόνο τοπική σημασία! Κόλλημα σε **ExStart/Exchange** = συνήθως **MTU mismatch**. Σταθερό **2-WAY** ανάμεσα σε DROthers = **κανονικό**.' },
          { t: 'quiz', q: 'Ένας router έχει Loopback0 2.2.2.2, Gi0/0 10.0.0.1 και Gi0/1 192.168.1.1. Δεν υπάρχει `router-id`. Ποιο είναι το RID;', opts: ['192.168.1.1', '10.0.0.1', '2.2.2.2', '0.0.0.0'], ok: 2, why: 'Οι **loopbacks** προηγούνται των φυσικών interfaces, ακόμα κι αν έχουν μικρότερη IP → **2.2.2.2**.' },
          { t: 'quiz', q: 'Ποιο από τα παρακάτω **δεν** χρειάζεται να ταιριάζει για να γίνουν δύο routers OSPF neighbors;', opts: ['Area ID', 'Hello/Dead timers', 'OSPF process ID', 'Subnet του link'], ok: 2, why: 'Το **process ID** είναι τοπικό. Τα υπόλοιπα πρέπει να ταιριάζουν.' },
          { t: 'quiz', q: 'Ποιο OSPF πακέτο μεταφέρει τα **πλήρη** LSAs;', opts: ['Hello', 'DBD', 'LSR', 'LSU'], ok: 3, why: 'Το **LSU** (Link-State Update) μεταφέρει τα LSAs. Το DBD είναι μόνο περίληψη και το LSR είναι αίτημα.' },
        ],
      },
      {
        id: 'ccna-3-5', title: 'OSPF ΙΙ: ρύθμιση single-area, wildcard, passive, cost', minutes: 24,
        goal: 'Να ρυθμίζεις single-area OSPFv2 με `network` + wildcard ή με `ip ospf area` στο interface, να ορίζεις router-id, passive interfaces, να διαφημίζεις default route και να ελέγχεις/αλλάζεις το OSPF cost.',
        blocks: [
          { t: 'text', md: '### Δύο τρόποι να ενεργοποιήσεις OSPF σε interfaces\n1. **`network <διεύθυνση> <wildcard> area <αριθμός>`** κάτω από `router ospf`: ενεργοποιεί OSPF σε **κάθε interface** του οποίου η IP «ταιριάζει».\n2. **`ip ospf <process> area <αριθμός>`** απευθείας στο interface: πιο ξεκάθαρο.\n\n### Wildcard mask\nΕίναι η **ανάποδη μάσκα**: **0 = «πρέπει να ταιριάζει»**, **1 = «δεν με νοιάζει»**. Υπολογίζεται εύκολα: **255.255.255.255 − μάσκα**.\n- /24 (255.255.255.0) → `0.0.0.255`\n- /30 (255.255.255.252) → `0.0.0.3`\n- /26 (255.255.255.192) → `0.0.0.63`\n- Ένα συγκεκριμένο interface: `10.0.12.1 0.0.0.0` (ακριβές ταίριασμα)\n- Όλα τα interfaces: `0.0.0.0 255.255.255.255`\n\nΤο `network` **δεν** διαφημίζει απευθείας το δίκτυο που γράφεις. Ενεργοποιεί OSPF στα interfaces που ταιριάζουν, και το OSPF διαφημίζει **τα subnets αυτών των interfaces**.' },
          { t: 'code', lang: 'cisco', title: 'Single-area OSPFv2 στον R1', code: 'interface Loopback0\n ip address 1.1.1.1 255.255.255.255\n!\nrouter ospf 1\n router-id 1.1.1.1\n network 192.168.1.0 0.0.0.255 area 0\n network 10.0.12.0 0.0.0.3 area 0\n passive-interface GigabitEthernet0/0\n default-information originate\n auto-cost reference-bandwidth 10000\n!\n! εναλλακτικά, ανά interface:\ninterface GigabitEthernet0/1\n ip ospf 1 area 0\n ip ospf cost 10',
            explain: '- `router ospf 1`: το **1** είναι process ID, με **τοπική** σημασία.\n- `router-id 1.1.1.1`: σταθερό, προβλέψιμο RID.\n- `network 192.168.1.0 0.0.0.255 area 0`: OSPF στο LAN interface (Gi0/0).\n- `network 10.0.12.0 0.0.0.3 area 0`: OSPF στο /30 link προς τον R2.\n- `passive-interface g0/0`: **δεν στέλνει Hellos** στο LAN (εκεί δεν υπάρχουν routers), αλλά **συνεχίζει να διαφημίζει** το subnet του. Ασφάλεια και λιγότερη άσκοπη κίνηση.\n- `default-information originate`: διαφημίζει τη **δική του default route** (πρέπει να υπάρχει, π.χ. static προς ISP) σε όλους τους OSPF routers.\n- `auto-cost reference-bandwidth 10000`: reference σε **Mbps** (εδώ 10 Gbps). Βάλ’ το **ίδιο σε όλους** τους routers.\n- `ip ospf cost 10`: χειροκίνητο κόστος σε interface, που υπερισχύει του υπολογισμού.' },
          { t: 'text', md: '### OSPF cost\n**Cost = reference bandwidth / interface bandwidth**. Προεπιλογή reference = **100 Mbps**. Ελάχιστο cost = 1.' },
          { t: 'table', head: ['Interface', 'Bandwidth', 'Cost (ref 100 Mbps)', 'Cost (ref 10.000 Mbps)'], rows: [
            ['Ethernet', '10 Mbps', '10', '1000'], ['FastEthernet', '100 Mbps', '**1**', '100'], ['GigabitEthernet', '1 Gbps', '**1** ⚠', '10'], ['10-Gigabit', '10 Gbps', '**1** ⚠', '1'],
          ] },
          { t: 'warn', md: 'Με την προεπιλογή, **FastEthernet, Gigabit και 10G έχουν όλα cost 1**: το OSPF δεν μπορεί να τα ξεχωρίσει! Γι’ αυτό αλλάζουμε το `auto-cost reference-bandwidth`. Άλλοι τρόποι να επηρεάσεις το cost: `ip ospf cost` (άμεσα) ή η εντολή `bandwidth` στο interface (αλλάζει μόνο την τιμή που χρησιμοποιείται στους υπολογισμούς, όχι την πραγματική ταχύτητα).' },
          { t: 'cli', title: 'Lab: OSPF ανάμεσα σε R1 και R2', prompt: 'R1(config)#', banner: 'R1: Gi0/0 = 192.168.1.1/24 (LAN), Gi0/1 = 10.0.12.1/30 (προς R2)',
            steps: [
              { task: 'Ξεκίνα τη διεργασία **OSPF 1**.', expect: '^router\\s+ospf\\s+1$', ans: 'router ospf 1', next: 'R1(config-router)#' },
              { task: 'Όρισε router-id **1.1.1.1**.', expect: '^router-id\\s+' + ip('1.1.1.1') + '$', ans: 'router-id 1.1.1.1' },
              { task: 'Ενεργοποίησε OSPF στο LAN **192.168.1.0/24** στην **area 0**.', expect: '^net(work)?\\s+' + ip('192.168.1.0') + '\\s+' + ip('0.0.0.255') + '\\s+area\\s+0(\\.0\\.0\\.0)?$', ans: 'network 192.168.1.0 0.0.0.255 area 0' },
              { task: 'Ενεργοποίησε OSPF στο link **10.0.12.0/30** στην **area 0**.', expect: '^net(work)?\\s+' + ip('10.0.12.0') + '\\s+' + ip('0.0.0.3') + '\\s+area\\s+0(\\.0\\.0\\.0)?$', ans: 'network 10.0.12.0 0.0.0.3 area 0',
                out: '%OSPF-5-ADJCHG: Process 1, Nbr 2.2.2.2 on GigabitEthernet0/1 from LOADING to FULL, Loading Done' },
              { task: 'Κάνε **passive** τη Gi0/0 (το LAN).', expect: '^passive(-interface)?\\s+g(i(g(abit(ethernet)?)?)?)?\\s*0/0$', ans: 'passive-interface g0/0' },
              { task: 'Γύρνα στο `#`.', expect: RX.end, ans: 'end', next: 'R1#' },
              { task: 'Δες τους OSPF neighbors.', expect: '^' + SH + 'ip\\s+ospf\\s+nei(ghbors?)?$', ans: 'show ip ospf neighbor',
                out: 'Neighbor ID     Pri   State           Dead Time   Address         Interface\n2.2.2.2           1   FULL/DR         00:00:35    10.0.12.2       GigabitEthernet0/1' },
              { task: 'Δες μόνο τις OSPF routes: `show ip route ospf`.', expect: '^' + SH + 'ip\\s+ro(ute)?\\s+ospf$', ans: 'show ip route ospf',
                out: 'O     192.168.2.0/24 [110/2] via 10.0.12.2, 00:00:41, GigabitEthernet0/1' },
            ], done: 'Ο R1 είναι **FULL** με τον R2 και έμαθε το LAN του R2 με cost 2 (1 για το link + 1 για το LAN του R2). Ο R2 φαίνεται **DR**: το Ethernet είναι broadcast network type, ο R2 ήταν ήδη στο segment και έχει και μεγαλύτερο RID. Αυτό είναι το θέμα του επόμενου μαθήματος.' },
          { t: 'exam', md: 'Υπολογισμός wildcard: **255 − κάθε octet της μάσκας**. Παγίδα: το **passive-interface** σταματά τα Hellos αλλά **διαφημίζει** κανονικά το δίκτυο. Το `default-information originate` απαιτεί να υπάρχει ήδη default route στον router (εκτός αν προσθέσεις `always`). OSPF route στον πίνακα = **O**, AD **110**.' },
          { t: 'quiz', q: 'Ποια είναι η wildcard για το subnet **172.16.8.0/21**;', opts: ['0.0.7.255', '0.0.8.255', '255.255.248.0', '0.0.3.255'], ok: 0, why: '/21 = 255.255.**248**.0 → 255−248 = **7** → wildcard **0.0.7.255**.' },
          { t: 'quiz', q: 'Τι κάνει το `passive-interface g0/0` στο OSPF;', opts: ['Απενεργοποιεί το interface', 'Σταματά τα Hellos στη g0/0, αλλά το subnet της διαφημίζεται κανονικά', 'Αφαιρεί το subnet από το OSPF', 'Κάνει τον router DR'], ok: 1, why: 'Δεν σχηματίζονται γειτνιάσεις στο interface, αλλά το δίκτυό του **συνεχίζει να διαφημίζεται**.' },
          { t: 'quiz', q: 'Με την προεπιλεγμένη reference bandwidth, ποιο είναι το OSPF cost ενός GigabitEthernet;', opts: ['1', '4', '10', '100'], ok: 0, why: '100 Mbps / 1000 Mbps = 0,1 → στρογγυλεύεται στο ελάχιστο **1**. Γι’ αυτό αλλάζουμε το reference bandwidth.' },
        ],
      },
      {
        id: 'ccna-3-6', title: 'OSPF ΙΙΙ: network types, DR/BDR και troubleshooting', minutes: 22,
        goal: 'Να ξεχωρίζεις broadcast και point-to-point network types, να προβλέπεις ποιος θα γίνει DR/BDR, να επηρεάζεις την εκλογή με priority και να διαβάζεις `show ip ospf neighbor` και `show ip ospf interface`.',
        blocks: [
          { t: 'text', md: 'Φαντάσου 5 routers στον ίδιο switch (ένα Ethernet segment). Αν ο καθένας έκανε **Full** γειτνίαση με όλους, θα είχαμε 5×4/2 = 10 γειτνιάσεις και πολλαπλά αντίγραφα κάθε LSA. Λύση: εκλέγεται ένας **«πρόεδρος της πολυκατοικίας»**, ο **DR (Designated Router)**, και ένας αναπληρωτής, ο **BDR**. Όλοι μιλούν μόνο με αυτούς.\n\n### Network types\n- **Broadcast** (προεπιλογή σε **Ethernet**): εκλογή **DR/BDR**, hello 10 s / dead 40 s.\n- **Point-to-point** (προεπιλογή σε serial, π.χ. HDLC/PPP): **χωρίς DR/BDR**, ταχύτερη σύγκλιση, hello 10 s / dead 40 s. Σε Ethernet link με **μόνο δύο** routers είναι best practice: `ip ospf network point-to-point`.\n\n### Εκλογή DR/BDR\n1. Υψηλότερη **OSPF interface priority** (0–255, **προεπιλογή 1**).\n2. Σε ισοπαλία, υψηλότερο **Router ID**.\n3. **Priority 0** = δεν γίνεται **ποτέ** DR ή BDR.\n4. Η εκλογή είναι **non-preemptive**: αν μπει αργότερα router με μεγαλύτερη priority, **δεν** παίρνει τη θέση. Ο BDR γίνεται DR μόνο αν πέσει ο DR (ή αν γίνει `clear ip ospf process`).\n\n### Ποιοι γίνονται FULL;\n- Κάθε router είναι **FULL** με τον **DR** και τον **BDR**.\n- Οι υπόλοιποι (**DROTHERs**) μένουν σε **2-WAY** μεταξύ τους, και αυτό είναι **φυσιολογικό**!\n- Οι DROthers στέλνουν updates στο **224.0.0.6** (DR/BDR), και ο DR τα αναμεταδίδει στο **224.0.0.5** (όλους).' },
          { t: 'code', lang: 'cisco', title: 'Επηρέασε την εκλογή και άλλαξε network type', code: 'interface GigabitEthernet0/0\n ip ospf priority 100\n!\ninterface GigabitEthernet0/0\n ip ospf priority 0\n!\ninterface GigabitEthernet0/1\n ip ospf network point-to-point\n!\ninterface GigabitEthernet0/0\n ip ospf hello-interval 5\n ip ospf dead-interval 20',
            explain: '- `ip ospf priority 100`: στον router που θέλουμε για DR (π.χ. τον πιο ισχυρό).\n- `ip ospf priority 0`: σε router που **δεν** θέλουμε ποτέ για DR/BDR (π.χ. υποκατάστημα με αδύναμη CPU).\n- Η priority είναι **ανά interface**, οπότε ένας router μπορεί να είναι DR σε ένα segment και DROTHER σε άλλο.\n- `ip ospf network point-to-point`: σε Ethernet link με δύο routers. Χωρίς DR/BDR, χωρίς αναμονή εκλογής. Πρέπει να μπει **και στις δύο** πλευρές.\n- `hello-interval` / `dead-interval`: αν αλλάξουν, πρέπει να ταιριάζουν στους γείτονες.' },
          { t: 'cli', title: 'Lab: διάβασε την κατάσταση OSPF σε ένα κοινό Ethernet segment', prompt: 'R1#', banner: 'Τέσσερις routers (R1–R4) στο ίδιο VLAN 10.0.123.0/24, όλοι με priority 1.',
            steps: [
              { task: 'Δες τους neighbors.', expect: '^' + SH + 'ip\\s+ospf\\s+nei(ghbors?)?$', ans: 'show ip ospf neighbor',
                out: 'Neighbor ID     Pri   State           Dead Time   Address         Interface\n2.2.2.2           1   2WAY/DROTHER    00:00:38    10.0.123.2      GigabitEthernet0/0\n3.3.3.3           1   FULL/BDR        00:00:33    10.0.123.3      GigabitEthernet0/0\n4.4.4.4           1   FULL/DR         00:00:36    10.0.123.4      GigabitEthernet0/0' },
              { task: 'Δες σύνοψη των OSPF interfaces: `show ip ospf interface brief`.', expect: '^' + SH + 'ip\\s+ospf\\s+int(erface)?\\s+br(ief)?$', ans: 'show ip ospf interface brief',
                out: 'Interface    PID   Area            IP Address/Mask    Cost  State Nbrs F/C\nLo0          1     0               1.1.1.1/32         1     LOOP  0/0\nGi0/0        1     0               10.0.123.1/24      1     DROTH 3/2' },
              { task: 'Δες λεπτομέρειες για τη Gi0/0: `show ip ospf interface g0/0`.', expect: '^' + SH + 'ip\\s+ospf\\s+int(erface)?\\s*g(i(g(abit(ethernet)?)?)?)?\\s*0/0$', ans: 'show ip ospf interface g0/0',
                out: 'GigabitEthernet0/0 is up, line protocol is up\n  Internet Address 10.0.123.1/24, Area 0, Attached via Network Statement\n  Process ID 1, Router ID 1.1.1.1, Network Type BROADCAST, Cost: 1\n  Transmit Delay is 1 sec, State DROTHER, Priority 1\n  Designated Router (ID) 4.4.4.4, Interface address 10.0.123.4\n  Backup Designated router (ID) 3.3.3.3, Interface address 10.0.123.3\n  Timer intervals configured, Hello 10, Dead 40, Wait 40, Retransmit 5\n  Neighbor Count is 3, Adjacent neighbor count is 2\n    Adjacent with neighbor 3.3.3.3  (Backup Designated Router)\n    Adjacent with neighbor 4.4.4.4  (Designated Router)' },
              { task: 'Μπες σε global config.', expect: RX.conf, ans: 'conf t', next: 'R1(config)#' },
              { task: 'Μπες στη Gi0/0.', expect: '^' + GI('0/0') + '$', ans: 'interface g0/0', next: 'R1(config-if)#' },
              { task: 'Ο R1 είναι ο πιο ισχυρός router: δώσε του **priority 255** ώστε να γίνει DR στην επόμενη εκλογή.', expect: '^ip\\s+ospf\\s+pri(ority)?\\s+255$', ans: 'ip ospf priority 255' },
            ], done: 'Ο R1 **δεν** θα γίνει DR αμέσως, γιατί η εκλογή είναι **non-preemptive**. Θα γίνει μόνο όταν ξαναγίνει εκλογή (π.χ. πέσουν οι DR/BDR ή γίνει `clear ip ospf process` σε όλους).' },
          { t: 'text', md: '### Troubleshooting checklist\n1. `show ip ospf neighbor`: λείπει ο γείτονας; Κοίτα area, subnet, timers, passive, authentication, RID.\n2. Κολλημένο σε **INIT**: ο γείτονας δεν βλέπει τα δικά μου Hellos (ACL, μονόδρομο πρόβλημα).\n3. Κολλημένο σε **EXSTART/EXCHANGE**: **MTU mismatch**.\n4. `show ip ospf interface`: network type, cost, timers, DR/BDR.\n5. `show ip protocols`: RID, networks, passive interfaces, reference bandwidth.\n6. `show ip route ospf`: έφτασαν οι routes;' },
          { t: 'exam', md: 'Πρόβλεψη DR/BDR: **υψηλότερη priority, μετά υψηλότερο RID**, **priority 0 = ποτέ**, **non-preemptive** (μετράει ποιος ήταν ήδη εκεί). Το `2WAY/DROTHER` στο output είναι **φυσιολογικό** ανάμεσα σε δύο DROthers. Το `FULL/DR` σημαίνει ότι **ο γείτονας** είναι ο DR, όχι εσύ!' },
          { t: 'quiz', q: 'Τρεις routers σε Ethernet: R1 (RID 1.1.1.1, prio 1), R2 (RID 2.2.2.2, prio 1), R3 (RID 3.3.3.3, prio 0). Ξεκινούν ταυτόχρονα. Ποιος γίνεται DR;', opts: ['R1', 'R2', 'R3', 'Κανείς'], ok: 1, why: 'Ο R3 έχει **priority 0**, άρα αποκλείεται. Ανάμεσα σε R1 και R2 (ίδια priority) κερδίζει το **υψηλότερο RID** → **R2** DR, R1 BDR.' },
          { t: 'quiz', q: 'Σε ποια κατάσταση μένουν δύο **DROTHER** routers μεταξύ τους;', opts: ['FULL', '2-WAY', 'EXSTART', 'INIT'], ok: 1, why: 'Οι DROthers γίνονται FULL μόνο με DR/BDR. Μεταξύ τους μένουν σε **2-WAY**, και αυτό είναι φυσιολογικό.' },
          { t: 'quiz', q: 'Ποιος network type **δεν** εκλέγει DR/BDR;', opts: ['Broadcast', 'Point-to-point', 'Non-broadcast (NBMA)', 'Όλοι εκλέγουν'], ok: 1, why: 'Στο **point-to-point** υπάρχει μόνο ένας γείτονας, οπότε δεν χρειάζεται DR.' },
          { t: 'quiz', q: 'Δύο OSPF γείτονες κολλάνε στην κατάσταση **EXSTART**. Ποια είναι η πιθανότερη αιτία;', opts: ['Διαφορετική area', 'MTU mismatch', 'Διαφορετικό process ID', 'Διαφορετικό hostname'], ok: 1, why: 'Το **MTU mismatch** χαλάει την ανταλλαγή DBD. Μια διαφορετική area θα εμπόδιζε τη γειτνίαση πολύ νωρίτερα (δεν θα έφταναν καν σε 2-WAY).' },
        ],
      },
      {
        id: 'ccna-3-7', title: 'First Hop Redundancy: HSRP, VRRP, GLBP', minutes: 18,
        goal: 'Να εξηγείς τι πρόβλημα λύνει ένα FHRP, πώς δουλεύει το HSRP (active/standby, virtual IP/MAC, priority, preempt), και να συγκρίνεις HSRP, VRRP και GLBP.',
        blocks: [
          { t: 'text', md: 'Κάθε PC έχει **ένα** default gateway. Αν ο router-gateway πέσει, το PC μένει **απομονωμένο**, ακόμα κι αν υπάρχει δεύτερος router δίπλα. Δεν μπορείς να αλλάξεις το gateway σε 500 PCs με το χέρι!\n\nΈνα **FHRP (First Hop Redundancy Protocol)** κάνει δύο (ή περισσότερους) routers να μοιράζονται μια **εικονική IP** και μια **εικονική MAC**. Τα PCs έχουν ως gateway την εικονική IP. Ένας router απαντά κάθε στιγμή, και αν πέσει, τη θέση του παίρνει ο άλλος **χωρίς** τα PCs να καταλάβουν τίποτα. Σαν ένα τηλεφωνικό κέντρο με **ένα** νούμερο και δύο τηλεφωνητές.' },
          { t: 'anim', scene: 'ccna-hsrp-failover', caption: 'HSRP: ο Active πέφτει, ο Standby αναλαμβάνει την ίδια virtual IP/MAC.' },
          { t: 'table', head: ['', 'HSRP', 'VRRP', 'GLBP'], rows: [
            ['Πρότυπο', 'Cisco', '**IETF** (ανοιχτό, RFC 5798)', 'Cisco'],
            ['Ρόλοι', '**Active** / **Standby**', '**Master** / **Backup**', '**AVG** / **AVF** (έως 4 AVFs)'],
            ['Load balancing', 'Όχι ανά group (μόνο με πολλά groups/VLANs)', 'Όχι ανά group', '**Ναι**, μέσα στο ίδιο group'],
            ['Virtual MAC', 'v1: 0000.0c07.acXX · v2: 0000.0c9f.fXXX', '0000.5e00.01XX', '0007.b400.XXYY'],
            ['Multicast', 'v1: 224.0.0.2 · v2: 224.0.0.102', '224.0.0.18', '224.0.0.102'],
            ['Προεπιλεγμένη priority', '100', '100', '100'],
            ['Preemption', '**Ανενεργή** εξ ορισμού', '**Ενεργή** εξ ορισμού', 'Ανενεργή (για AVG)'],
          ] },
          { t: 'text', md: '### HSRP λεπτομέρειες\n- **Active**: ο router με την **υψηλότερη priority** (σε ισοπαλία, την υψηλότερη IP στο interface).\n- Hello κάθε **3 s**, hold time **10 s**.\n- Χωρίς **preempt**, ένας router με μεγαλύτερη priority που επανέρχεται **δεν** παίρνει πίσω τον ρόλο Active.\n- **HSRPv2**: groups 0–4095 (αντί για 0–255), υποστηρίζει IPv6, millisecond timers.\n- Συνηθισμένο design: διαφορετικός Active router ανά VLAN (π.χ. R1 για VLAN 10, R2 για VLAN 20), ώστε να χρησιμοποιούνται και οι δύο.' },
          { t: 'code', lang: 'cisco', title: 'HSRP στον R1 (Active) και R2 (Standby)', code: '! R1\ninterface GigabitEthernet0/0\n ip address 192.168.1.1 255.255.255.0\n standby version 2\n standby 1 ip 192.168.1.254\n standby 1 priority 110\n standby 1 preempt\n!\n! R2\ninterface GigabitEthernet0/0\n ip address 192.168.1.2 255.255.255.0\n standby version 2\n standby 1 ip 192.168.1.254',
            explain: '- Κάθε router έχει **δική του** πραγματική IP (.1, .2) και **κοινή** virtual IP (.254), που μπαίνει ως default gateway στο DHCP των PCs.\n- `standby version 2`: HSRPv2. Πρέπει να ταιριάζει στους routers του group.\n- `standby 1 ip …`: group 1 και virtual IP. Ο αριθμός group πρέπει να ταιριάζει.\n- `standby 1 priority 110`: ο R1 κερδίζει (ο R2 έχει την προεπιλογή, 100).\n- `standby 1 preempt`: όταν ο R1 επανέλθει μετά από βλάβη, **ξαναπαίρνει** τον ρόλο Active.' },
          { t: 'cli', title: 'Lab: HSRP στον R1', prompt: 'R1(config)#',
            steps: [
              { task: 'Μπες στη **Gi0/0**.', expect: '^' + GI('0/0') + '$', ans: 'interface g0/0', next: 'R1(config-if)#' },
              { task: 'Όρισε HSRP group **1** με virtual IP **192.168.1.254**.', expect: '^standby\\s+1\\s+ip\\s+' + ip('192.168.1.254') + '$', ans: 'standby 1 ip 192.168.1.254',
                out: '%HSRP-5-STATECHANGE: GigabitEthernet0/0 Grp 1 state Speak -> Standby\n%HSRP-5-STATECHANGE: GigabitEthernet0/0 Grp 1 state Standby -> Active' },
              { task: 'Δώσε **priority 110**.', expect: '^standby\\s+1\\s+pri(ority)?\\s+110$', ans: 'standby 1 priority 110' },
              { task: 'Ενεργοποίησε **preempt**.', expect: '^standby\\s+1\\s+preempt$', ans: 'standby 1 preempt' },
              { task: 'Γύρνα στο `#`.', expect: RX.end, ans: 'end', next: 'R1#' },
              { task: 'Επαλήθευσε: `show standby brief`.', expect: '^' + SH + 'standby\\s+br(ief)?$', ans: 'show standby brief',
                out: '                     P indicates configured to preempt.\n                     |\nInterface   Grp  Pri P State   Active          Standby         Virtual IP\nGi0/0       1    110 P Active  local           192.168.1.2     192.168.1.254' },
            ], done: 'Ο R1 είναι **Active** (local) και ο R2 (.2) είναι **Standby**. Το **P** δείχνει ότι το preempt είναι ενεργό.' },
          { t: 'exam', md: 'Στο blueprint ζητείται **ο σκοπός** των FHRP (3.5 *Describe the purpose, functions, and concepts*), αλλά οι ερωτήσεις συχνά ρωτούν και λεπτομέρειες: **HSRP = Active/Standby, Cisco**, **VRRP = Master/Backup, ανοιχτό**, **GLBP = load balancing, AVG/AVF**. Θυμήσου ότι στο HSRP το **preempt είναι off** εξ ορισμού, και τις virtual MAC **0000.0c07.acXX** (HSRPv1) / **0000.5e00.01XX** (VRRP).' },
          { t: 'quiz', q: 'Ποιο FHRP είναι **ανοιχτό πρότυπο**;', opts: ['HSRP', 'GLBP', 'VRRP', 'Και τα τρία'], ok: 2, why: 'Το **VRRP** είναι IETF πρότυπο. HSRP και GLBP είναι της Cisco.' },
          { t: 'quiz', q: 'Ο R1 (priority 120) ήταν Active, έπεσε, και ο R2 (priority 100) έγινε Active. Ο R1 επανέρχεται **χωρίς** preempt. Τι γίνεται;', opts: ['Ο R1 ξαναγίνεται Active αμέσως', 'Ο R2 παραμένει Active και ο R1 γίνεται Standby', 'Και οι δύο γίνονται Active', 'Το group πέφτει'], ok: 1, why: 'Χωρίς **preempt** ο R1 δεν «κλέβει» τον ρόλο, οπότε μένει **Standby**.' },
          { t: 'quiz', q: 'Ποιο FHRP μπορεί να κάνει **load balancing** σε πολλούς routers μέσα στο **ίδιο** group;', opts: ['HSRP', 'VRRP', 'GLBP', 'Κανένα'], ok: 2, why: 'Το **GLBP**: ο AVG δίνει διαφορετική virtual MAC (διαφορετικό AVF) σε διαφορετικούς clients.' },
          { t: 'quiz', q: 'Ποια είναι η virtual MAC για **HSRPv1 group 10**;', opts: ['0000.0c07.ac10', '0000.0c07.ac0a', '0000.5e00.010a', '0007.b400.0a01'], ok: 1, why: 'HSRPv1: 0000.0c07.ac**XX** όπου XX = group σε **hex**. 10 = 0x0a → **0000.0c07.ac0a**.' },
        ],
      },
    ],
  };

